#!/usr/bin/env node
/** Stamps the application version.
 *
 * The version is a hash of the CONTENT of every shipped file in public/ (except the generated files themselves and `_headers`), so it
 * changes exactly when something users receive changes, and it is reproducible: the same sources always give the same version.
 *
 * Writes two generated files, both committed:
 *   public/version.json    {"version": "<12 hex>"}  what the running app compares against (fetched with cache: 'no-store')
 *   public/sw-version.js   sets self.OPENROOM_VERSION and self.OPENROOM_ASSETS; imported by sw.js AND loaded by index.html.
 *                          Because sw.js imports it, the browser's service-worker update check sees new bytes whenever the version
 *                          changes. A byte-identical sw.js alone would NOT notice a changed stylesheet or script.
 *
 *   node scripts/stamp-version.mjs          write the files
 *   node scripts/stamp-version.mjs --check  exit 1 if the committed files do not match the current sources (used by tests and deploy)
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
export const GENERATED = ['version.json', 'sw-version.js'];
const NOT_HASHED = new Set([...GENERATED, '_headers']);
const NOT_PRECACHED = new Set(['index.html', 'version.json', '_headers', '404.html', 'sw.js']); // sw.js never caches itself; version.json must always come from the network

function listFiles(dir, base = dir) {
  return fs.readdirSync(dir, {withFileTypes: true}).flatMap(e => e.isDirectory() ? listFiles(path.join(dir, e.name), base) : [path.relative(base, path.join(dir, e.name)).split(path.sep).join('/')]).sort();
}
export function computeVersion(dir) {
  const hash = crypto.createHash('sha256');
  for (const file of listFiles(dir).filter(f => !NOT_HASHED.has(f))) hash.update(`${file}\0${crypto.createHash('sha256').update(fs.readFileSync(path.join(dir, file))).digest('hex')}\n`);
  return hash.digest('hex').slice(0, 12);
}
/** '/index.html' is deliberately absent: Cloudflare Static Assets answers it with a 307 redirect to '/', and redirected responses are never precached. The page is cached as '/'. */
export function precacheList(dir) {
  // '/sw-version.js' is listed explicitly so the result does not depend on whether the generated file exists yet (idempotent stamping)
  const files = new Set(['/', '/sw-version.js', ...listFiles(dir).filter(f => !NOT_PRECACHED.has(f)).map(f => `/${f}`)]);
  return [...files].sort((a, b) => a === '/' ? -1 : b === '/' ? 1 : a.localeCompare(b));
}
export function render(dir) {
  const version = computeVersion(dir);
  const assets = precacheList(dir);
  return {
    'version.json': `${JSON.stringify({name: 'Open Room ETHZ', version})}\n`,
    'sw-version.js': `/* GENERATED by scripts/stamp-version.mjs. Do not edit; run \`npm run stamp\`. */\nself.OPENROOM_VERSION = ${JSON.stringify(version)};\nself.OPENROOM_ASSETS = ${JSON.stringify(assets)};\n`
  };
}
export function check(dir) {
  const wanted = render(dir);
  return GENERATED.filter(f => !fs.existsSync(path.join(dir, f)) || fs.readFileSync(path.join(dir, f), 'utf8') !== wanted[f]);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const dir = path.join(root, 'public');
  if (process.argv.includes('--check')) {
    const stale = check(dir);
    if (stale.length) { console.error(`Version files out of date: ${stale.join(', ')}. Run: npm run stamp`); process.exit(1); }
    console.log('version files are current');
  } else {
    const out = render(dir);
    for (const [file, content] of Object.entries(out)) fs.writeFileSync(path.join(dir, file), content);
    console.log(`stamped version ${computeVersion(dir)} (${precacheList(dir).length} precached files)`);
  }
}
